import numpy as np
from scipy.optimize import minimize

def objective(vars):
    p, q, r, s = vars
    return p/q + r/p + s/r + q/s

def constraint(vars):
    p, q, r, s = vars
    return (p + s) * (r + q) - (p * s + q * r)

def find_min():
    # Trying different starting points to avoid local minima
    best_val = float('inf')
    for _ in range(20):
        start_point = np.random.uniform(0.1, 10.0, 4)
        res = minimize(objective, start_point, constraints={'type': 'eq', 'fun': constraint}, bounds=[(1e-6, None)]*4)
        if res.success and res.fun < best_val:
            best_val = res.fun
            best_params = res.x
    return best_val, best_params

print(find_min())

import numpy as np

def f(p, r, s):
    q = (p*s - r*(p+s)) / (p + s - r)
    if q <= 0:
        return float('inf')
    return p/q + r/p + s/r + q/s

def search():
    min_f = float('inf')
    for p in np.linspace(0.1, 10, 20):
        for s in np.linspace(0.1, 10, 20):
            # Case 1: r < ps/(p+s)
            for r in np.linspace(0.01, (p*s/(p+s)) - 0.01, 20):
                val = f(p, r, s)
                if val < min_f:
                    min_f = val
            # Case 2: r > p+s
            for r in np.linspace(p + s + 0.01, 20, 20):
                val = f(p, r, s)
                if val < min_f:
                    min_f = val
    return min_f

print(search())

