    if x <= 0 or y <= 0 or z <= 0:
        return 1e10
    return x + y + z + 1.0/(x*y*z)

def constraint(vars):
    x, y, z = vars
    return x*y + 1 + x*y**2 * z + y*z - x*y*z - y

def find_min():
    best_val = float('inf')
    for _ in range(100):
        start_point = np.random.uniform(0.1, 5.0, 3)
        res = minimize(objective, start_point, constraints={'type': 'eq', 'fun': constraint}, bounds=[(1e-6, None)]*3)
        if res.success and res.fun < best_val:
            best_val = res.fun
    return best_val

print(find_min())

